namespace sv_5ea4b12980284cd2943675235a45f2fb.Services;

public class WarehouseInfo
{
    public string SelectedWarehouseId { get; set; } = "WH-001";
    public string SelectedWarehouseName { get; set; } = "Warehouse A";

    public static readonly Dictionary<string, string> AvailableWarehouses = new()
    {
        ["WH-001"] = "Warehouse A",
        ["WH-002"] = "Warehouse B",
        ["WH-003"] = "Warehouse C",
        ["WH-004"] = "Warehouse D"
    };
}

namespace sv_5ea4b12980284cd2943675235a45f2fb.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for a warehouse.
/// Fires OnChange when new data arrives so all subscribed components update.
/// Scoped lifetime ensures each circuit (user) gets independent state.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LowStockCount { get; private set; }
    public string? CurrentWarehouseId { get; private set; }

    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query returning low-stock item count.
    /// </summary>
