@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@using sv_5ea4b12980284cd2943675235a45f2fb.Services

<div class="warehouse-selector">
    <label class="form-label text-white mb-1" for="warehouseSelect">Current Warehouse</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            value="@_selectedId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseInfo.AvailableWarehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    private string _selectedId = "WH-001";

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-001";
        var name = WarehouseInfo.AvailableWarehouses.GetValueOrDefault(_selectedId, "Unknown");
        var updated = new WarehouseInfo
        {
            SelectedWarehouseId = _selectedId,
            SelectedWarehouseName = name
        };
        await WarehouseSource.NotifyChangedAsync(updated);
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_5ea4b12980284cd2943675235a45f2fb.Services

<span class="badge rounded-pill @BadgeClass">@AlertService.LowStockCount</span>

@code {
    private Action? _handler;

    private string BadgeClass => AlertService.LowStockCount switch
    {
        > 10 => "bg-danger",
        > 5 => "bg-warning text-dark",
        > 0 => "bg-info",
        _ => "bg-secondary"
    };

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

