@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_5ea4b12980284cd2943675235a45f2fb.Services

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Current Warehouse</h5>
                <h2>@(_warehouse?.SelectedWarehouseName ?? "—")</h2>
                <p class="text-muted mb-0">@(_warehouse?.SelectedWarehouseId ?? "—")</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card @AlertCardClass">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <h2>@AlertService.LowStockCount</h2>
                <p class="mb-0">items below minimum</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Polling Status</h5>
                <h2>
                    @if (_isPolling)
                    {
                        <span class="text-success">● Active</span>
                    }
                    else
                    {
                        <span class="text-secondary">○ Stopped</span>
                    }
                </h2>
                <p class="text-muted mb-0">every 10 seconds</p>
            </div>
        </div>
    </div>
</div>

@if (_pollHistory.Count > 0)
{
    <h4>Recent Polls</h4>
    <table class="table table-sm table-striped">
        <thead>
            <tr>
                <th>Time</th>
                <th>Warehouse</th>
                <th>Low Stock Count</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var entry in _pollHistory.AsEnumerable().Reverse())
            {
                <tr>
                    <td>@entry.Time.ToString("HH:mm:ss")</td>
                    <td>@entry.WarehouseName</td>
                    <td>@entry.Count</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [CascadingParameter]
    private WarehouseInfo? _warehouse { get; set; }

    private CancellationTokenSource? _cts;
    private Action? _alertHandler;
    private bool _isPolling;

    private readonly List<PollEntry> _pollHistory = [];

    private string AlertCardClass => AlertService.LowStockCount switch
    {
        > 10 => "border-danger",
        > 5 => "border-warning",
        > 0 => "border-info",
        _ => ""
    };

    protected override void OnInitialized()
    {
        // Subscribe to alert changes so we re-render when polling updates the service,
        // even if the poll was triggered by this component — the sidebar badge also
        // subscribes, so the single OnChange event updates both.
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _alertHandler;
    }

    protected override async Task OnParametersSetAsync()
    {
        // Restart polling whenever the warehouse changes.
        await StopPollingAsync();
        await StartPollingAsync();
    }

    private async Task StartPollingAsync()
    {
        if (_warehouse is null) return;

        // Fetch immediately, then poll every 10 seconds.
        await AlertService.RefreshAsync(_warehouse.SelectedWarehouseId);
        RecordPoll();

        _cts = new CancellationTokenSource();
        _isPolling = true;
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
                if (ct.IsCancellationRequested) break;

                await AlertService.RefreshAsync(_warehouse!.SelectedWarehouseId);
                await InvokeAsync(() =>
                {
                    RecordPoll();
                    StateHasChanged();
                });
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private void RecordPoll()
    {
        _pollHistory.Add(new PollEntry(
            DateTime.Now,
            _warehouse!.SelectedWarehouseName,
            AlertService.LowStockCount));

        if (_pollHistory.Count > 20)
            _pollHistory.RemoveAt(0);
    }

    private async Task StopPollingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
        _isPolling = false;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _alertHandler;
        _cts?.Cancel();
        _cts?.Dispose();
    }

    private record PollEntry(DateTime Time, string WarehouseName, int Count);
}

